const translations={ru:{"nav-home":"Главная","nav-courses":"Курсы","nav-about":"О нас","nav-contact":"Контакты","nav-signup":"Записаться","hero-title":"Присоединяйтесь к","hero-subtitle":"будущему технологий","hero-course":"Робототехника и Программирование для детей","hero-button":"Изучить курсы >","stats-title":"Ведущая IT-школа Казахстана для детей","stats-students":"ДОВОЛЬНЫХ УЧЕНИКОВ","stats-robots":"СОЗДАННЫХ РОБОТОВ","stats-wins":"ПОБЕД В СОРЕВНОВАНИЯХ","about-title":"О TechLab Digital Solutions","about-text":"Мы - ведущая IT-школа робототехники и программирования для детей. Наша миссия - подготовить новое поколение к цифровому будущему через практическое обучение и творческий подход к технологиям.","about-learn":"Изучай","about-learn-text":"Изучай программирование и робототехнику с лучшими преподавателями и современными методиками обучения.","about-create":"Создавай","about-create-text":"Создавай собственных роботов, программы и проекты, которые станут частью твоего портфолио.","about-compete":"Соревнуйся","about-compete-text":"Участвуй в соревнованиях по робототехнике и программированию, показывай свои навыки и получай признание.","courses-title":"Наши Курсы","courses-subtitle":"Откройте для себя мир технологий с нашими специализированными курсами.","footer-tagline":"Где технологии встречаются с будущим.","footer-links":"ПОЛЕЗНЫЕ ССЫЛКИ","footer-contact":"СВЯЗАТЬСЯ С НАМИ","footer-social":"МЫ В СОЦСЕТЯХ","footer-courses":"Курсы","footer-privacy":"Политика конфиденциальности","footer-refund":"Возврат и отмена","footer-terms":"Условия использования"},kz:{"nav-home":"Басты бет","nav-courses":"Курстар","nav-about":"Біз туралы","nav-contact":"Байланыс","nav-signup":"Тіркелу","hero-title":"Технологиялардың болашағына","hero-subtitle":"қосылыңыз","hero-course":"Балаларға арналған робототехника және бағдарламалау","hero-button":"Курстарды зерттеу >","stats-title":"Қазақстанның жетекші IT-мектебі балаларға арналған","stats-students":"ҚАНАҒАТТАНҒАН ОҚУШЫЛАР","stats-robots":"ЖАСАЛҒАН РОБОТТАР","stats-wins":"ЖАРЫСТАҒЫ ЖЕҢІСТЕР","about-title":"TechLab Digital Solutions туралы","about-text":"Біз - балаларға арналған робототехника мен бағдарламалаудың жетекші IT-мектебіміз. Біздің миссиямыз - практикалық оқыту және технологияларға шығармашылық көзқарас арқылы жаңа ұрпақты цифрлық болашаққа дайындау.","about-learn":"Үйрен","about-learn-text":"Үздік мұғалімдер мен заманауи оқыту әдістемелерімен бағдарламалау мен робототехниканы үйреніңіз.","about-create":"Жаса","about-create-text":"Өз роботтарыңызды, бағдарламаларыңызды және портфолионыңыздың бөлігі болатын жобаларыңызды жасаңыз.","about-compete":"Жарыс","about-compete-text":"Робототехника мен бағдарламалау жарыстарына қатысып, дағдыларыңызды көрсетіп, мойындау алыңыз.","courses-title":"Біздің Курстар","courses-subtitle":"Біздің мамандандырылған курстарымызбен технологиялар әлемін ашыңыз.","footer-tagline":"Технологиялар болашақпен кездесетін жер.","footer-links":"ПАЙДАЛЫ СІЛТЕМЕЛЕР","footer-contact":"БІЗБЕН БАЙЛАНЫСУ","footer-social":"ӘЛЕУМЕТТІК ЖЕЛІЛЕРДЕ","footer-courses":"Курстар","footer-privacy":"Құпиялылық саясаты","footer-refund":"Қайтару және бас тарту","footer-terms":"Пайдалану шарттары"}};function switchLanguage(lang){const elements=document.querySelectorAll("[data-translate]");elements.forEach(element=>{const key=element.getAttribute("data-translate");if(translations[lang]&&translations[lang][key]){element.textContent=translations[lang][key]}});localStorage.setItem("preferred-language",lang);document.documentElement.lang=lang}document.addEventListener("DOMContentLoaded",function(){const languageSelect=document.getElementById("language-select");if(languageSelect){const savedLang=localStorage.getItem("preferred-language")||"ru";languageSelect.value=savedLang;if(savedLang!=="ru"){switchLanguage(savedLang)}languageSelect.addEventListener("change",function(){switchLanguage(this.value)})}});